/**
 * Which local Supabase stack a script talks to (M11a-0).
 *
 *   (default)       the development stack: supabase/config.toml, project "my-game-dex"
 *   MGD_STACK=test  the isolated test stack: .supabase-test/supabase/config.toml,
 *                   project "my-game-dex-test", its own containers, volumes and ports
 *                   (generated by scripts/test-stack.mjs, never committed)
 *
 * Every script reads the project, container, CLI arguments and status from here, so
 * none can mix the two. Both stacks must answer on a loopback address, and each must
 * be the project it claims to be.
 *
 * Protection for the development stack: when ~/.my-game-dex/protect-dev-stack exists,
 * anything that asks for the stack's status through stackStatus() (every check, fixture
 * and mutation script) refuses the development stack unless MGD_ALLOW_DEV_STACK=1. The
 * development stack can still be started, stopped and used by the app.
 */
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
export const cli = join(root, "node_modules", "supabase", "dist", "supabase.js");

export const DEV_PROJECT_ID = "my-game-dex";
export const TEST_PROJECT_ID = "my-game-dex-test";
/** The test stack's ports are the development ports plus this. */
export const TEST_PORT_OFFSET = 1000;
export const DEV_PROTECTION_MARKER = join(homedir(), ".my-game-dex", "protect-dev-stack");

const requested = process.env.MGD_STACK ?? "dev";
if (requested !== "dev" && requested !== "test") {
  throw new Error(`MGD_STACK must be "dev" or "test", not "${requested}".`);
}
export const stackName = requested;
export const testStackDir = join(root, ".supabase-test");
/** The directory the Supabase CLI treats as the project (its --workdir). */
export const stackDir = stackName === "test" ? testStackDir : root;
export const stackConfigPath = join(stackDir, "supabase", "config.toml");

if (!existsSync(stackConfigPath)) {
  throw new Error(stackName === "test" ? "The test stack isn't prepared. Run npm run test-stack:start." : `Missing ${stackConfigPath}.`);
}
export const stackConfig = readFileSync(stackConfigPath, "utf8");
export const projectId = /project_id\s*=\s*"([^"]+)"/.exec(stackConfig)?.[1];
const expectedProject = stackName === "test" ? TEST_PROJECT_ID : DEV_PROJECT_ID;
if (projectId !== expectedProject) {
  throw new Error(`Refusing: the ${stackName} stack's config names project "${projectId}", not "${expectedProject}".`);
}
const apiPort = Number(/\[api\][\s\S]*?\nport\s*=\s*(\d+)/.exec(stackConfig)?.[1]);

/** Extra Supabase CLI arguments that select this stack. */
export const workdirArgs = stackName === "test" ? ["--workdir", stackDir] : [];
export const dbContainer = `supabase_db_${projectId}`;

/** Throws if destructive work would target the protected development stack. */
export function guardDevStack(label = "this script") {
  if (stackName === "dev" && existsSync(DEV_PROTECTION_MARKER) && process.env.MGD_ALLOW_DEV_STACK !== "1") {
    throw new Error(
      `Refusing to run ${label} against the protected development stack (${DEV_PROTECTION_MARKER} exists). ` +
        "Use the isolated test stack: npm run test-stack:run -- <npm script>.",
    );
  }
}

/** Checks that a status really describes this stack: loopback, and this stack's API port. */
export function assertStackStatus(status) {
  const url = new URL(status?.API_URL ?? "http://invalid");
  if (!["127.0.0.1", "localhost", "::1", "[::1]"].includes(url.hostname)) {
    throw new Error(`Refusing: the stack's API is on ${url.hostname}, not a loopback address.`);
  }
  if (Number(url.port) !== apiPort) {
    throw new Error(`Refusing: the ${stackName} stack should answer on port ${apiPort}, but its status says ${url.port}.`);
  }
  return status;
}

/**
 * The running stack's status (URLs and local development keys), checked to be this
 * stack, after the development-stack guard. Keys are never printed by callers.
 */
export function stackStatus({ label } = {}) {
  guardDevStack(label);
  let status;
  try {
    status = JSON.parse(execFileSync(process.execPath, [cli, "status", "-o", "json", ...workdirArgs], { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }));
  } catch {
    throw new Error(stackName === "test" ? "The test stack isn't running. Run npm run test-stack:start." : "The local stack isn't running. Try npm run db:start.");
  }
  return assertStackStatus(status);
}
